import os
import time
import subprocess
import shutil
import threading

class NFSMonitor:
    def __init__(self, nfs_dir, tar_dir, interval=10):
        self.nfs_dir = nfs_dir
        self.tar_dir = tar_dir
        self.interval = interval
        self.stop_event = threading.Event()

    def monitor_nfs(self):
        if not os.path.exists(self.nfs_dir):
            raise FileNotFoundError(f"NFS directory {self.nfs_dir} does not exist.")
        if not os.path.exists(self.tar_dir):
            os.makedirs(self.tar_dir)

        while not self.stop_event.is_set():
            self.create_tar_archive()
            time.sleep(self.interval)

    def create_tar_archive(self):
        timestamp = time.strftime("%Y%m%d-%H%M%S")
        tar_path = os.path.join(self.tar_dir, f"backup_{timestamp}.tar")
        subprocess.run(["tar", "-cvzf", tar_path, "-C", os.path.dirname(self.nfs_dir), os.path.basename(self.nfs_dir)])
        self.cleanup_old_archives()

    def cleanup_old_archives(self):
        max_archives = 5
        for file in os.listdir(self.tar_dir):
            if file.endswith('.tar'):
                file_path = os.path.join(self.tar_dir, file)
                timestamp = file.split('_')[1].split('.')[0]
                if time.time() - int(timestamp) > 3600:  # Remove files older than 1 hour
                    os.remove(file_path)

    def start_monitoring(self):
        threading.Thread(target=self.monitor_nfs).start()

    def stop_monitoring(self):
        self.stop_event.set()

def main():
    nfs_directory = "/path/to/nfs"
    tar_directory = "/path/to/tar"
    monitor = NFSMonitor(nfs_directory, tar_directory)
    monitor.start_monitoring()
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        monitor.stop_monitoring()

if __name__ == "__main__":
    main()

