def is_safe(board, row, col):
    """Task: write a Python function is_safe(board, row, col) to return True if placing a queen at the given position on a partially filled nxn chessboard would violate row or column or diagonal attack restrictions. The argument board is a list of tuples, where each tuple represents a row on the board, and takes the form (row_index, col_index), and row and col are ints 0 <= i < n. Return False if everything is safe.
    """
    # Check row
    for i in range(col):
        if board[row][i][1] == col:
            return False

    # Check diagonal (left-to-right)
    for i, j in board:
        if j < col and i - j == row - col:
            return False

    # Check diagonal (right-to-left)
    for i, j in board:
        if j < col and i + j == row + col:
            return False

    return True


